static void shablock(sha256_ctx*c,const uint8_t*p){uint32_t w[64],a,b,d,e,f,g,h,t1,t2,cc;unsigned i;for(i=0;i<16;i++)w[i]=((uint32_t)p[4*i]<<24)|((uint32_t)p[4*i+1]<<16)|((uint32_t)p[4*i+2]<<8)|p[4*i+3];for(i=16;i<64;i++){uint32_t s0=rr(w[i-15],7)^rr(w[i-15],18)^(w[i-15]>>3),s1=rr(w[i-2],17)^rr(w[i-2],19)^(w[i-2]>>10);w[i]=w[i-16]+s0+w[i-7]+s1;}a=c->h[0];b=c->h[1];cc=c->h[2];d=c->h[3];e=c->h[4];f=c->h[5];g=c->h[6];h=c->h[7];for(i=0;i<64;i++){uint32_t S1=rr(e,6)^rr(e,11)^rr(e,25),ch=(e&f)^((~e)&g),S0=rr(a,2)^rr(a,13)^rr(a,22),maj=(a&b)^(a&cc)^(b&cc);t1=h+S1+ch+K[i]+w[i];t2=S0+maj;h=g;g=f;f=e;e=d+t1;d=cc;cc=b;b=a;a=t1+t2;}c->h[0]+=a;c->h[1]+=b;c->h[2]+=cc;c->h[3]+=d;c->h[4]+=e;c->h[5]+=f;c->h[6]+=g;c->h[7]+=h;}
static void shainit(sha256_ctx*c){static const uint32_t I[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};memcpy(c->h,I,sizeof(I));c->bits=0;c->n=0;}
static void shaupdate(sha256_ctx*c,const uint8_t*p,size_t n){size_t z;c->bits+=(uint64_t)n*8u;while(n){z=64-c->n;if(z>n)z=n;memcpy(c->b+c->n,p,z);c->n+=z;p+=z;n-=z;if(c->n==64){shablock(c,c->b);c->n=0;}}}
