static int openssl_verify(void*ctx,const uint8_t*k,size_t kn,const uint8_t*m,size_t mn,const uint8_t*s,size_t sn){EVP_PKEY*pk=NULL;EVP_MD_CTX*md=NULL;int ok=0;(void)ctx;if(!k||kn!=32||(!m&&mn)||!s||sn!=64)return K20;pk=EVP_PKEY_new_raw_public_key(EVP_PKEY_ED25519,NULL,k,kn);md=EVP_MD_CTX_new();if(pk&&md&&EVP_DigestVerifyInit(md,NULL,NULL,NULL,pk)==1&&EVP_DigestVerify(md,s,sn,m,mn)==1)ok=1;EVP_MD_CTX_free(md);EVP_PKEY_free(pk);return ok?K0:K23;}
