static int canon_prefix(char*out,size_t cap,const char*in){char d[PATH_MAX],r[PATH_MAX];const char*b,*slash;size_t dl;if(!out||!in||!*in||strstr(in,"/../")||!strcmp(in,".."))return K20;slash=strrchr(in,'/');if(slash){dl=(size_t)(slash-in);if(!dl){strcpy(d,"/");}else{if(dl>=sizeof d)return K9;memcpy(d,in,dl);d[dl]=0;}b=slash+1;}else{strcpy(d,".");b=in;}if(!*b||!strcmp(b,".")||!strcmp(b,"..")||strchr(b,'/'))return K20;if(!realpath(d,r))return K4;return snprintf(out,cap,"%s/%s",r,b)>0&&strlen(r)+1+strlen(b)<cap?K0:K9;}
